import{_ as t,o as a,c as i,m as r}from"./chunks/framework.D3-xQjZb.js";const m=JSON.parse('{"title":"About Keith Williams","description":"Meet Keith Williams, NJIT’s Enterprise AI program director. Explore his work in software engineering, public services in Zambia, and AI-assisted learning.","frontmatter":{"title":"About Keith Williams","description":"Meet Keith Williams, NJIT’s Enterprise AI program director. Explore his work in software engineering, public services in Zambia, and AI-assisted learning.","teaser":"I build software, design courses, and study how people decide whether to trust an AI-assisted result. My route here runs through Pittsburgh, Newark, and Zambia."},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),n={name:"about.md"};function o(s,e,h,l,d,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="about-keith-williams" tabindex="-1">About Keith Williams <a class="header-anchor" href="#about-keith-williams" aria-label="Permalink to &quot;About Keith Williams&quot;">​</a></h1><p>I’m Keith Williams, a Senior University Lecturer in Informatics at the New Jersey Institute of Technology and director of its B.S. in Enterprise AI. I’ve built software for learning and collaboration, taught mobile development at ZCAS University in Zambia, and worked with Zambia’s Ministry of Finance on digital public services.</p><p>Across those settings, I keep coming back to a practical question. What happens when the person who built the system hands it to the person who needs it? It shapes how I design courses, test software, and think about human judgment in AI. <a href="/teaching">Inside my classroom</a> · <a href="/research/systems/">My engineering case studies</a></p><h2 id="where-it-started" tabindex="-1">Where it started <a class="header-anchor" href="#where-it-started" aria-label="Permalink to &quot;Where it started&quot;">​</a></h2><p>My father worked as a mainframe systems lead operator at Alcoa. My own way into computing was a Tandy TRS-80 Color Computer 2 at home. That’s where I taught myself to program.</p><p>Later, through AmeriCorps, I taught children about computers at an after-school center in Pittsburgh. I’ve also worked with high schools. I still think about the person sitting down at a computer for the first time, wondering what they’re allowed to try.</p><h2 id="building-things-teaching-people" tabindex="-1">Building things, teaching people <a class="header-anchor" href="#building-things-teaching-people" aria-label="Permalink to &quot;Building things, teaching people&quot;">​</a></h2><p>I started teaching at NJIT as an adjunct. I’ve developed courses and helped shape the Web and Information Systems program. Along the way I built Showedme.net, a web application framework and learning management system, and Wrkbench, an iOS collaboration app.</p><p>Today my students use AI coding assistants. In the classroom exercises I call Studios, I can give the assistant a job and reserve a decision for the student. In one game starter, all twelve tests passed before anyone had written the rule for winning. <a href="/teaching/when-ai-helps-write-the-code">Read the classroom story</a></p><h2 id="learning-beyond-my-own-classroom" tabindex="-1">Learning beyond my own classroom <a class="header-anchor" href="#learning-beyond-my-own-classroom" aria-label="Permalink to &quot;Learning beyond my own classroom&quot;">​</a></h2><p>An NJIT graduate student from Zambia connected me with ZCAS University. In our progressive web application workshop there, students and staff began building an app for student registration. I also worked with Zambia’s Ministry of Finance on digitizing public services. A registration form still gives me a good question to take into class. After someone clicks Submit, how do they know their registration went through? <a href="https://news.njit.edu/inspiring-students-njit-africa" target="_blank" rel="noreferrer">NJIT on teaching in Zambia</a> · <a href="https://news.njit.edu/njit-lecturer-helps-digitize-government-services-zambia" target="_blank" rel="noreferrer">NJIT on digitizing government services</a></p><h2 id="what-im-working-on-now" tabindex="-1">What I’m working on now <a class="header-anchor" href="#what-im-working-on-now" aria-label="Permalink to &quot;What I’m working on now {#what-im-working-on-now}&quot;">​</a></h2><p>Two questions keep coming up in my work with AI. How do we tell what someone learned when AI helped them build? How do we trace a confident answer back to the evidence behind it? My research agenda describes the studies I’d like to run. You can also try that second question yourself using three fictional reports from a harbor. <a href="/research">Explore the research</a> · <a href="/knowledge-lab/guide/walkthrough" target="_self">Try the three-report exercise</a> · <a href="/#projects">See the projects</a></p><p>In MetaVis, my Swift and Metal video-editing prototype, checking a rendered frame and checking an exported video tell you different things. I wrote up the tests so another engineer can inspect the distinction. <a href="/research/systems/metavis-evidence-and-evaluation">Inside MetaVis</a></p><p><a href="/life-tracker">Life Tracker</a> explains how I carry the same habit into everyday work with an AI assistant. A separate proposal, EverydayAI Newark, imagines paid workshops helping fund free community learning. It is a proposal, not an operating program.</p><h2 id="lets-compare-notes" tabindex="-1">Let’s compare notes <a class="header-anchor" href="#lets-compare-notes" aria-label="Permalink to &quot;Let’s compare notes {#lets-compare-notes}&quot;">​</a></h2><p>For independent consulting, I’m interested in the step where someone has to double-check an AI result before handing it to a customer or colleague. If your team has a step like that, tell me what the person receives and what they check by hand. That gives us a specific workflow to discuss. <a href="https://www.linkedin.com/in/keithwilliams5/" target="_blank" rel="noreferrer">Contact me on LinkedIn about consulting</a></p><p>If you teach with AI or want to collaborate on a study, I’d like to hear which decision you want a learner to make independently. My faculty profile lists my university email. <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">Contact me at NJIT</a></p><p>For a reproducible issue with one of my public projects, include the project link and what you observed. <a href="/#conversation">Start a public project conversation</a></p><p><em>Parts of this account first appeared on my <a href="https://eaikw.com/about/" target="_blank" rel="noreferrer">earlier About page</a>.</em></p>',20)])])}const u=t(n,[["render",o]]);export{m as __pageData,u as default};
